Plan:
- Parse each Input filter string into the target fields, treating `=` as one value and `IN LIST` as multiple values.
- Expand each input row by the Cartesian product of `orgId`, `careType`, `specialtyId`, and `contextId`, ignoring other filter fields and omitting leading zeros.
- Write the header and computed rows into `Output!A1:G10`, leaving undefined cells blank.

```python
import shutil
import re
import itertools
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Input" not in vals.sheetnames:
    raise ValueError("Input sheet not found")
if "Output" not in wb.sheetnames:
    wb.create_sheet("Output")

ws_in = vals["Input"]
ws_out = wb["Output"]

def norm(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        if float(v).is_integer():
            return int(v)
        return v
    s = str(v).strip()
    if s == "":
        return None
    if re.fullmatch(r"[+-]?\d+", s):
        return int(s)
    if re.fullmatch(r"[+-]?\d*\.\d+", s):
        return float(s)
    return s

def parse_filter(text):
    parsed = {}
    if text is None:
        return parsed
    s = str(text).strip().rstrip(";").strip()
    if not s:
        return parsed

    # Matches clauses like:
    # ("field" = "value")
    # ("field" IN LIST 1,2,3)
    for m in re.finditer(r'\("([^"]+)"\s*(=|IN\s+LIST)\s*([^)]*)\)', s, re.IGNORECASE):
        field = m.group(1).strip()
        op = m.group(2).upper()
        valstr = m.group(3).strip()

        if op == "=":
            val = valstr.strip().strip('"')
            parsed.setdefault(field, []).append(norm(val))
        else:
            if valstr:
                for item in valstr.split(","):
                    item = item.strip().strip('"')
                    if item != "":
                        parsed.setdefault(field, []).append(norm(item))
            else:
                parsed.setdefault(field, []).append(None)

    return parsed

target_fields = ["orgId", "careType", "specialtyId", "contextId"]
header = ["wtype_id", "name", "status", "orgId", "careType", "specialtyId", "contextId"]

out_rows = []

for r in range(2, ws_in.max_row + 1):
    wtype = ws_in.cell(r, 1).value
    name = ws_in.cell(r, 2).value
    status = ws_in.cell(r, 3).value
    filt = ws_in.cell(r, 4).value

    if wtype is None and name is None and status is None and filt is None:
        continue

    parsed = parse_filter(filt)

    lists = []
    for f in target_fields:
        vlist = parsed.get(f, [])
        if not vlist:
            lists.append([None])
        else:
            lists.append(vlist)

    for combo in itertools.product(*lists):
        out_rows.append([
            norm(wtype),
            norm(name),
            norm(status),
            combo[0],
            combo[1],
            combo[2],
            combo[3],
        ])

# Clear the graded answer region before writing.
for r in range(1, 11):
    for c in range(1, 8):
        ws_out.cell(r, c).value = None

for c, h in enumerate(header, start=1):
    ws_out.cell(1, c).value = h

for i, row in enumerate(out_rows, start=2):
    if i > 10:
        break
    for c, v in enumerate(row, start=1):
        ws_out.cell(i, c).value = v

wb.save(OUT)

print("computed rows:", len(out_rows))
for row in out_rows[:10]:
    print(row)
